implementation:
#include <stdlib.h>
#include <string.h>

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  ImageInfo *clone_info = CloneImageInfo(image_info);
  char filename[MaxTextLength];
  FILE *file = NULL;
  Image *new_image = NULL;

  if (clone_info == (ImageInfo *) NULL) {
    return image;
  }

  GetPathComponent(image->filename, TailPath, filename);
  (void) FormatLocaleString(filename, MaxTextLength, "%.1024s", filename);

  file = fopen(filename, "wb");
  if (file == (FILE *) NULL) {
    CloneImageInfo(clone_info);
    return image;
  }

  if (fwrite((void *) (image->pixels + PS_Offset), sizeof(PixelPacket), (size_t) PS_Size, file) != (size_t) PS_Size) {
    fclose(file);
    CloneImageInfo(clone_info);
    return image;
  }

  fclose(file);

  if (IsPostscriptFormat(filename) != MagickTrue) {
    CloneImageInfo(clone_info);
    return image;
  }

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL) {
    CloneImageInfo(clone_info);
    return image;
  }

  DestroyImageList(image);
  image = new_image;

  CloneImageInfo(clone_info);
  return image;
}
